use lg_core::{AccountId, Date, Money, Txn};
use lg_fmt::Locale;
use lg_report::render::transactions_table;

#[test]
fn disc_l12() {
    let acc = AccountId::parse("ativo:banco").unwrap();
    let txn = |d: u8, desc: &str| Txn::new(Date::ymd(2024, 3, d), acc.clone(), desc, Money::of(-100, "BRL")).with_category("mercado");
    let rows = [txn(1, "PADARIA BOM PAO LTDA FILIAL 2"), txn(2, "ACOUGUE SAO JOAO"), txn(3, "AÇOUGUE SÃO JOÃO")];
    let refs: Vec<&Txn> = rows.iter().collect();
    let out = transactions_table(&refs, &Locale::by_tag("pt-BR").unwrap());
    let col = |l: &str| l[..l.find("mercado").unwrap()].chars().count();
    let lines: Vec<&str> = out.lines().collect();
    assert_eq!(col(lines[3]), col(lines[2]), "{out}");
    assert_eq!(col(lines[4]), col(lines[2]), "{out}");
    assert_eq!(lines[4].chars().count(), lines[3].chars().count(), "{out}");
}
